head.script:
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.Dbclick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireDbClick(el);
}
scwin.checkValue = function(id, value) {
    if (WebSquare.wUnit.getDomById($p.id + id).innerText == value) {
        return true;
    }
    return false
}
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. Sorce 탭에서 useCtrlOnMultisort='false' 인지 확인한다.
    //1. In the Sorce tab, make sure useCtrlOnMultisort = 'false'.
    //Verify step 1. useCtrlOnMultisort = 'false'
    //Test step 2. 브라우저에서 컬럼을 Sort 한다.
    //2. Sort the column in the browser.
    //Verify step 2. The column is sorted in the browser.            
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick($p.id+'wq_uuid_3_column7')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkValue($p.id+'wq_uuid_3_cell_0_1', '1')", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkValue($p.id+'wq_uuid_3_cell_1_1', '2')", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkValue($p.id+'wq_uuid_3_cell_2_1', '3')", "true");
    // Test step 3. 3. 다른 컬럼을 Sort 한다.
    // 3. Sort the other columns.
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick($p.id+'wq_uuid_3_column9')");
    WebSquare.wUnit.addCommand("pause", "500");
    // Verify step 3. 3. 다른 컬럼도 Sort 된다. (MultiSort)
    // 3. Other columns are also sorted. (MultiSort)
    WebSquare.wUnit.addCommand("assert", "scwin.checkValue($p.id+'wq_uuid_3_cell_0_0', '3')", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkValue($p.id+'wq_uuid_3_cell_1_0', '2')", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkValue($p.id+'wq_uuid_3_cell_2_0', '1')", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 21-Feb-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
